pub(crate) fn canonical_database_path(path: &Path) -> Result<PathBuf> {
    canonical_database_path_inner(path, 0)
}

fn canonical_database_path_inner(path: &Path, depth: usize) -> Result<PathBuf> {
    if depth > 32 {
        return Err(Error::Other(format!(
            "too many symlink levels while canonicalizing {}",
            path.display()
        )));
    }
    if let Ok(metadata) = std::fs::symlink_metadata(path)
        && metadata.file_type().is_symlink()
    {
        let target = std::fs::read_link(path)
            .map_err(|err| Error::Other(format!("read_link {}: {err}", path.display())))?;
        let resolved = if target.is_absolute() {
            target
        } else {
            path.parent()
                .filter(|parent| !parent.as_os_str().is_empty())
                .unwrap_or_else(|| Path::new("."))
                .join(target)
        };
        return canonical_database_path_inner(&resolved, depth + 1);
    }
    if path.exists() {
        return std::fs::canonicalize(path)
            .map_err(|err| Error::Other(format!("canonicalize {}: {err}", path.display())));
    }
    let parent = path
        .parent()
        .filter(|parent| !parent.as_os_str().is_empty())
        .unwrap_or_else(|| Path::new("."));
    let file_name = path.file_name().ok_or_else(|| {
        Error::Other(format!(
            "database path must include a file name: {}",
            path.display()
        ))
    })?;
    let canonical_parent = std::fs::canonicalize(parent)
        .map_err(|err| Error::Other(format!("canonicalize {}: {err}", parent.display())))?;
    Ok(canonical_parent.join(file_name))
}

struct OpenRegistryReservation {
    path: PathBuf,
    active: bool,
}

/// What a handle on a store is FOR, and therefore whether the store waits for
/// it.
///
/// A store is held open by the handle that acquired it and by every live
/// reader looking at it. It is NOT held open by the handles its own components
/// keep for themselves — the owner service's view of the store it serves, a
/// background worker's view of the store it maintains — because those live for
/// as long as the process does. Counting them would mean the store is never
/// let go and the next opener is told forever that it is taken.
#[derive(Clone, Copy, PartialEq, Eq)]
pub(crate) enum HandleRole {
    /// Acquired the store's resources; hands them over rather than releasing
    /// them while a reader is still looking.
    Owner,
    /// A caller reading the store. The store outlives the owner for as long as
    /// one of these is alive.
    Reader,
    /// A view the store keeps for its own machinery. Waits for nothing.
    Internal,
}

impl HandleRole {
    /// Whether the store waits for this handle before it is released.
    const fn holds_the_store(self) -> bool {
        matches!(self, Self::Owner | Self::Reader)
    }
}

/// What a store still owes, and who is left to pay it.
///
/// Every handle on one store shares this. The owner handle is the one that
/// ACQUIRED the store's resources, but it is not necessarily the last to let
/// go: a session a blocked request or a suspended cursor is holding keeps the
/// store alive after the owner handle is gone. Releasing while such a reader
/// is still inside would pull the store out from under it and tell the next
/// opener the store is free while somebody is still reading it.
///
/// So the owner hands what it holds to this record instead, and whichever
/// holder turns out to be the last one pays it out on the way down.
pub(crate) struct StoreFinalization {
    live_holders: AtomicUsize,
    pending: Mutex<Option<PendingStoreRelease>>,
    vector: Arc<VectorStore>,
    accountant: Arc<MemoryAccountant>,
    non_vector_memory: Mutex<Option<RetainedNonVectorMemoryOwner>>,
}

/// The standing relational and graph allocations owned by one database life.
/// Their existing mutation paths admit and release the same estimates; this
/// final owner returns exactly the objects still present when the last handle
/// disappears. Vector allocations carry their own object-local reservations.
struct RetainedNonVectorMemoryOwner {
    relational: Arc<RelationalStore>,
    graph: Arc<GraphStore>,
    accountant: Arc<MemoryAccountant>,
}

impl Drop for RetainedNonVectorMemoryOwner {
    fn drop(&mut self) {
        let metadata = self.relational.table_meta.read().clone();
        let metadata_bytes = metadata.values().fold(0usize, |bytes, meta| {
            bytes.saturating_add(meta.estimated_bytes())
        });
        let row_bytes =
            self.relational
                .tables
                .read()
                .iter()
                .fold(0usize, |bytes, (table, rows)| {
                    let meta = metadata.get(table);
                    // Only a live version still owns a charge: a version
                    // carrying `deleted_tx` handed its bytes back at the
                    // commit that stamped it (`DeleteReleaseBytes`), and
                    // `account_loaded_state` charges the same live set.
                    bytes.saturating_add(
                        rows.iter()
                            .filter(|row| {
                                row.deleted_tx.is_none()
                                    || self.relational.is_retention_expired(
                                        table,
                                        row.row_id,
                                        row.created_tx,
                                    )
                            })
                            .fold(0usize, |row_bytes, row| {
                                row_bytes.saturating_add(meta.map_or_else(
                                    || row.estimated_bytes(),
                                    |meta| retained_row_bytes_for_meta(&row.values, meta, true),
                                ))
                            }),
                    )
                });
        let edge_bytes = self
            .graph
            .forward_adj
            .read()
            .values()
            .flatten()
            .fold(0usize, |bytes, edge| {
                bytes.saturating_add(edge.estimated_bytes())
            });
        self.accountant.release(
            metadata_bytes
                .saturating_add(row_bytes)
                .saturating_add(edge_bytes),
        );
    }
}

/// The resources an owner acquired, waiting for the last holder to release.
struct PendingStoreRelease {
    persistence: Option<Arc<RedbPersistence>>,
    open_registry_path: Option<PathBuf>,
    owner_read_service: Option<Arc<crate::owner_read::OwnerReadService>>,
    /// Present only when somebody else will pay this release out. A plugin is
    /// told the store closed by whoever actually finishes it, and a handle
    /// that finishes its own store is an ordinary drop, which owes the plugin
    /// nothing.
    plugin: Option<Arc<dyn DatabasePlugin>>,
}

impl StoreFinalization {
    fn new(
        relational: Arc<RelationalStore>,
        graph: Arc<GraphStore>,
        vector: Arc<VectorStore>,
        accountant: Arc<MemoryAccountant>,
    ) -> Arc<Self> {
        Arc::new(Self {
            live_holders: AtomicUsize::new(1),
            pending: Mutex::new(None),
            vector,
            accountant: accountant.clone(),
            non_vector_memory: Mutex::new(Some(RetainedNonVectorMemoryOwner {
                relational,
                graph,
                accountant,
            })),
        })
    }

    fn note_new_holder(&self) {
        self.live_holders.fetch_add(1, Ordering::SeqCst);
    }

    /// Whether the holder letting go now is the last one on this store.
    ///
    /// Counting past zero would be a bookkeeping fault rather than a release,
    /// so a count already at zero stays there and answers "not the last": the
    /// store has already been let go.
    fn note_holder_released(&self) -> bool {
        let last = self
            .live_holders
            .fetch_update(Ordering::SeqCst, Ordering::SeqCst, |live| {
                live.checked_sub(1)
            })
            .is_ok_and(|previous| previous == 1);
        if last {
            // Internal helper handles can outlive the last caller-facing
            // holder. They do not keep the store open and therefore must not
            // keep vector bodies or relational/F32 projection charges alive.
            for info in self.vector.index_layout_infos() {
                let removed = self
                    .vector
                    .deregister_index(&info.index, self.accountant.as_ref());
                let raw_bytes = removed
                    .iter()
                    .filter(|entry| entry.deleted_tx.is_none())
                    .fold(0usize, |bytes, entry| {
                        bytes.saturating_add(
                            info.layout.quantization.storage_bytes(entry.vector.len()),
                        )
                    });
                self.accountant.release(raw_bytes);
            }
            self.non_vector_memory.lock().take();
        }
        last
    }

    fn defer(&self, release: PendingStoreRelease) {
        *self.pending.lock() = Some(release);
    }

    fn take_pending(&self) -> Option<PendingStoreRelease> {
        self.pending.lock().take()
    }
}

/// Let go of everything an owner acquired for one store.
fn release_store(release: PendingStoreRelease) {
    if let Some(service) = &release.owner_read_service {
        service.release_channel();
        // The channel is gone and this owner will not take new work, so the
        // record beside the store says exactly that for as long as this writer
        // still holds it. A reader arriving inside that window is told the
        // owner is winding down instead of meeting a lock it cannot explain.
        if let Some(persistence) = &release.persistence {
            let _ = persistence.record_owner_read_status(service.status());
        }
    }
    if let Some(persistence) = &release.persistence {
        let _ = persistence.prepare_armed_migration_replacement();
        persistence.close();
    }
    if let Some(path) = &release.open_registry_path {
        release_open_registry_path(path);
    }
    // The plugin hears about the close from whoever ends the store. The handle
    // that opened it went away while a reader was still inside, so nothing
    // else is left to tell it, and it is told exactly once -- here.
    if let Some(plugin) = &release.plugin {
        let _closed = plugin.on_close();
    }
}

struct OpenFileRegistry {
    entries: Mutex<BTreeMap<PathBuf, OpenRegistryState>>,
    waiters: Condvar,
}

#[derive(Clone, Copy)]
enum OpenRegistryState {
    Opening { pid: u32 },
    Open { pid: u32 },
}

impl OpenRegistryState {
    fn pid(self) -> u32 {
        match self {
            Self::Opening { pid } | Self::Open { pid } => pid,
        }
    }

    fn is_opening(self) -> bool {
        matches!(self, Self::Opening { .. })
    }
}

struct DatabaseOperationGuard<'a> {
    db_id: DatabaseId,
    _lock: Option<parking_lot::RwLockReadGuard<'a, ()>>,
    // Every outer public operation observes one table-schema publication.
    // Local/received DDL already owns the write side before entering here, so
    // this re-entrant read acquisition never attempts a read-to-write upgrade.
    _schema_publication: Option<SchemaPublicationGuard<'a>>,
}

/// Serializes table-schema publication against a whole SQL statement. Local
/// table DDL takes the write side; ordinary statements and EXPLAIN take the
/// read side. It is deliberately separate from the close-operation gate:
/// schema writers may wait for readers without changing close semantics.
pub(crate) struct SchemaPublicationGuard<'a> {
    gate_id: usize,
    _read: Option<parking_lot::RwLockReadGuard<'a, ()>>,
    _write: Option<parking_lot::RwLockWriteGuard<'a, ()>>,
}

/// Internal transport-orchestration lease that keeps one outbound extraction
/// and its wire evidence on the same published table schema.
///
/// The compiled transport orchestration lives in this crate; the server-path copy
/// is an uncompiled exact-source audit mirror. This lease therefore remains
/// crate-private and adds no downstream database capability.
#[cfg(feature = "sync-orchestration")]
pub(crate) struct OutboundSyncSchemaReadGuard<'a> {
    _inner: SchemaPublicationGuard<'a>,
}

struct TriggerCloseWaiterGuard<'a> {
    trigger: &'a TriggerState,
}

impl Drop for DatabaseOperationGuard<'_> {
    fn drop(&mut self) {
        DB_OPERATION_STACK.with(|stack| {
            let popped = stack.borrow_mut().pop();
            debug_assert_eq!(
                popped,
                Some(self.db_id),
                "database operation stack mismatch"
            );
        });
    }
}

impl DatabaseOperationGuard<'_> {
    /// A maintenance cycle keeps the close barrier but must not pin one
    /// schema publication across long vector preparation. The vector path
    /// samples its declaration and rejects a candidate whose revision changed
    /// before publication, so online policy DDL can proceed while an old
    /// candidate is being built.
    fn release_schema_publication_for_online_maintenance(&mut self) {
        self._schema_publication.take();
    }
}

impl Drop for SchemaPublicationGuard<'_> {
    fn drop(&mut self) {
        SCHEMA_PUBLICATION_STACK.with(|stack| {
            let popped = stack.borrow_mut().pop();
            debug_assert_eq!(
                popped,
                Some(self.gate_id),
                "schema publication stack mismatch"
            );
        });
    }
}

impl<'a> TriggerCloseWaiterGuard<'a> {
    fn new(trigger: &'a TriggerState) -> Self {
        trigger.close_waiter_count.fetch_add(1, Ordering::SeqCst);
        Self { trigger }
    }
}

impl Drop for TriggerCloseWaiterGuard<'_> {
    fn drop(&mut self) {
        self.trigger
            .close_waiter_count
            .fetch_sub(1, Ordering::SeqCst);
        self.trigger.waiters.notify_all();
    }
}

impl OpenRegistryReservation {
    fn acquire(path: PathBuf) -> Result<Self> {
        let registry = open_file_registry();
        let mut entries = registry.entries.lock();
        loop {
            match entries.get(&path).copied() {
                Some(state) if state.is_opening() => {
                    registry.waiters.wait(&mut entries);
                }
                Some(state) => {
                    return Err(Error::DatabaseLocked {
                        holder_pid: state.pid(),
                        path,
                    });
                }
                None => {
                    entries.insert(
                        path.clone(),
                        OpenRegistryState::Opening {
                            pid: std::process::id(),
                        },
                    );
                    return Ok(Self { path, active: true });
                }
            }
        }
    }

    fn disarm(mut self) -> PathBuf {
        let registry = open_file_registry();
        let mut entries = registry.entries.lock();
        entries.insert(
            self.path.clone(),
            OpenRegistryState::Open {
                pid: std::process::id(),
            },
        );
        registry.waiters.notify_all();
        self.active = false;
        self.path.clone()
    }
}

impl Drop for OpenRegistryReservation {
    fn drop(&mut self) {
        if self.active {
            let registry = open_file_registry();
            let mut entries = registry.entries.lock();
            if entries
                .get(&self.path)
                .copied()
                .is_some_and(|state| state.is_opening() && state.pid() == std::process::id())
            {
                entries.remove(&self.path);
                registry.waiters.notify_all();
            }
        }
    }
}

/// `readers` is the runtime directory this deployment's direct readers publish
/// themselves in, so a refusal names the readers actually holding the store.
/// `None` means nobody stated one and the platform default is where they are.
fn acquire_registry_and_persistence(
    canonical_path: &Path,
    open_disposition: OpenDisposition,
) -> Result<(OpenRegistryReservation, Arc<RedbPersistence>)> {
    let retry_deadline = Instant::now() + SAME_PROCESS_REOPEN_RETRY;
    let cross_process_retry_deadline = Instant::now() + CROSS_PROCESS_LOCK_SETTLE_RETRY;

    loop {
        let registry_reservation =
            match OpenRegistryReservation::acquire(canonical_path.to_path_buf()) {
                Ok(reservation) => reservation,
                Err(Error::DatabaseLocked { holder_pid, path })
                    if holder_pid == std::process::id()
                        && path == canonical_path
                        && Instant::now() < retry_deadline =>
                {
                    wait_for_open_registry_change(Duration::from_millis(1));
                    continue;
                }
                Err(err) => return Err(err),
            };

        // This is the one place a writable open decides between taking a
        // store and bringing one into being, so it is the only place the
        // disposition can be enforced without inventing a second door. Under
        // `ExistingOnly` the existence question is not asked at all -- asking
        // it and then acting on the answer is precisely the race the
        // disposition exists to remove -- the ordinary open is attempted, and
        // the attempt's own "nothing here" is the typed refusal.
        let persistence = match open_disposition {
            OpenDisposition::ExistingOnly => RedbPersistence::open_existing_only(canonical_path),
            OpenDisposition::CreateIfMissing => {
                if canonical_path.exists() {
                    RedbPersistence::open(canonical_path)
                } else {
                    RedbPersistence::create(canonical_path)
                }
            }
        };

        match persistence {
            Ok(persistence) => return Ok((registry_reservation, Arc::new(persistence))),
            Err(Error::DatabaseLocked { holder_pid, path })
                if holder_pid == std::process::id()
                    && path == canonical_path
                    && Instant::now() < retry_deadline =>
            {
                drop(registry_reservation);
                wait_for_open_registry_change(Duration::from_millis(1));
            }
            Err(Error::DatabaseLocked { holder_pid, path })
                if holder_pid != std::process::id()
                    && path == canonical_path
                    && Instant::now() < cross_process_retry_deadline =>
            {
                drop(registry_reservation);
                wait_for_open_registry_change(Duration::from_millis(1));
            }
            Err(Error::ReadFailure(failure))
                if failure.kind() == ReadFailureKind::HeldByWriter
                    && Instant::now() < cross_process_retry_deadline =>
            {
                drop(registry_reservation);
                wait_for_open_registry_change(Duration::from_millis(1));
            }
            // HeldByReaders deliberately falls through: Redb has already
            // proved reader contention, so writer open refuses on this one
            // attempt instead of spending the writer-settle retry window.
            Err(err) => return Err(err),
        }
    }
}

fn acquire_registry_and_legacy_migration(
    canonical_path: &Path,
) -> Result<(OpenRegistryReservation, LegacyMigrationOpenCapability)> {
    let retry_deadline = Instant::now() + SAME_PROCESS_REOPEN_RETRY;
    let cross_process_retry_deadline = Instant::now() + CROSS_PROCESS_LOCK_SETTLE_RETRY;

    loop {
        let registry_reservation =
            match OpenRegistryReservation::acquire(canonical_path.to_path_buf()) {
                Ok(reservation) => reservation,
                Err(Error::DatabaseLocked { holder_pid, path })
                    if holder_pid == std::process::id()
                        && path == canonical_path
                        && Instant::now() < retry_deadline =>
                {
                    wait_for_open_registry_change(Duration::from_millis(1));
                    continue;
                }
                Err(error) => return Err(error),
            };

        match RedbPersistence::acquire_legacy_migration_capability(canonical_path) {
            Ok(capability) => return Ok((registry_reservation, capability)),
            Err(Error::DatabaseLocked { holder_pid, path })
                if holder_pid == std::process::id()
                    && path == canonical_path
                    && Instant::now() < retry_deadline =>
            {
                drop(registry_reservation);
                wait_for_open_registry_change(Duration::from_millis(1));
            }
            Err(Error::DatabaseLocked { holder_pid, path })
                if holder_pid != std::process::id()
                    && path == canonical_path
                    && Instant::now() < cross_process_retry_deadline =>
            {
                drop(registry_reservation);
                wait_for_open_registry_change(Duration::from_millis(1));
            }
            Err(Error::ReadFailure(failure))
                if failure.kind() == ReadFailureKind::HeldByWriter
                    && Instant::now() < cross_process_retry_deadline =>
            {
                drop(registry_reservation);
                wait_for_open_registry_change(Duration::from_millis(1));
            }
            // A direct-reader lock is definitive and never enters the writer
            // settle retry window.
            Err(error) => return Err(error),
        }
    }
}

fn wait_for_open_registry_change(timeout: Duration) {
    let registry = open_file_registry();
    let mut entries = registry.entries.lock();
    registry.waiters.wait_for(&mut entries, timeout);
}

fn release_open_registry_path(path: &Path) {
    let registry = open_file_registry();
    let mut entries = registry.entries.lock();
    if entries
        .get(path)
        .copied()
        .is_some_and(|state| state.pid() == std::process::id())
    {
        entries.remove(path);
        registry.waiters.notify_all();
    }
}

fn closed_database_error() -> Error {
    Error::Other("database handle is closed".to_string())
}

impl Database {
    pub(crate) fn custody_runtime(&self) -> Option<crate::custody::policy::Runtime> {
        self.custody_runtime.lock().clone()
    }
    pub(crate) fn set_custody_runtime(
        &self,
        tenant: TenantId,
        node: String,
        signer: crate::custody::preparation::LineageSigner,
    ) {
        *self.custody_runtime.lock() = Some(crate::custody::policy::Runtime {
            tenant,
            node,
            signer,
        });
    }

    pub(crate) fn stage_delivery_registration(
        &self,
        tx: TxId,
        registration: crate::custody::preparation::SourceRegistration,
    ) -> Result<()> {
        // A rejected registration aborts the writing transaction.
        let validated = self.tx_mgr.with_write_set(tx, |ws| {
            crate::custody::preparation::validate_registration(self, ws, &registration)?;
            ws.requires_commit_lsn = true;
            Ok(())
        })?;
        if let Err(error) = validated {
            self.rollback(tx)?;
            return Err(error);
        }
        self.pending_commit_metadata
            .lock()
            .entry(tx)
            .or_default()
            .delivery_registrations
            .push(registration);
        Ok(())
    }

    pub(crate) fn commit_delivery_prepared(
        &self,
        tx: TxId,
        prepare: &mut crate::custody::preparation::CommitPreparation<'_>,
    ) -> Result<()> {
        self.tx_mgr
            .with_write_set(tx, |ws| ws.requires_commit_lsn = true)?;
        self.commit_with_source_and_sync_ddl_and_trigger_audit_projection(
            tx,
            CommitSource::User,
            &[],
            &[],
            None,
            None,
            false,
            Some(prepare),
        )
        .map(|_| ())
    }

    pub(crate) fn rotate_custody_incarnation(
        &self,
        tenant: &TenantId,
        hub: &str,
        previous: Incarnation,
        next: Incarnation,
    ) -> Result<()> {
        use crate::custody::{canonical::*, preparation::*, records::*};
        let runtime = self.custody_runtime().ok_or_else(invalid)?;
        if runtime.tenant != *tenant || runtime.node != hub || self.retention_sync_peer().is_some()
        {
            return Err(invalid());
        }
        let signer = runtime.signer;
        let tx = self.begin()?;
        let mut installed = false;
        self.commit_delivery_prepared(tx, &mut |db, ws| {
            if db.existing_sync_incarnation(tenant)? != Some(previous) {
                return Ok(Vec::new());
            }
            let state = StateRecord {
                state: StateRef {
                    logical_store_id: uuid::Uuid::new_v4(),
                    incarnation: next,
                    birth_id: uuid::Uuid::new_v4(),
                    token: random_digest(),
                },
                parent: None,
                sequence: 0,
                retirement_root: crate::custody::authority::empty_history_root(),
            };
            let old = db.custody_records()?;
            let mut bindings = old
                .iter()
                .filter_map(|r| match r {
                    Record::Binding(b)
                        if b.namespace.tenant == *tenant
                            && b.namespace.hub_node == hub
                            && b.namespace.hub_incarnation == previous =>
                    {
                        Some(b.clone())
                    }
                    _ => None,
                })
                .collect::<Vec<_>>();
            // A declared snapshot can predate every binding.
            // The authenticated hub runtime already owns the tenant and identity.
            let mut records = state_records(db, state.clone(), tenant, hub)?;
            for b in &mut bindings {
                b.namespace.hub_incarnation = next;
                b.issuance_state = state.state.clone();
                b.issuance_source = (ws.commit_lsn.ok_or_else(invalid)?, 0);
                b.signature = signer(&b.bytes()?)?;
                records.push(Record::Binding(b.clone()));
            }
            ws.config_writes.push((
                tenant.config_key("sync_incarnation"),
                RedbPersistence::encode_config_value(&next.to_hex())?,
            ));
            installed = true;
            Ok(records)
        })?;
        if installed {
            self.sync_incarnations
                .lock()
                .insert(tenant.as_str().into(), next);
        }
        Ok(())
    }

    pub(crate) fn commit_delivery_metadata<F>(&self, prepare: F) -> Result<()>
    where
        F: FnOnce(Lsn) -> Result<Vec<crate::custody::records::Record>>,
    {
        let tx = self.begin()?;
        let mut prepare = Some(prepare);
        self.commit_delivery_prepared(tx, &mut |_, ws| {
            prepare
                .take()
                .ok_or_else(crate::custody::canonical::invalid)?(
                ws.commit_lsn
                    .ok_or_else(crate::custody::canonical::invalid)?,
            )
        })
    }

    /// A snapshot-in-time read of "is this handle closed right now" — reads
    /// the SAME two atomics `open_operation` checks, but takes NO lock and
    /// holds nothing: unlike `open_operation`'s guard, this cannot be held
    /// across a park/wait. Exists ONLY to let a `Result`-returning surface
    /// reject an ALREADY-closed handle before doing any work that would
    /// otherwise panic on it (`execute`'s snapshot-registration pre-flight,
    /// which resolves through the panicking public `Database::snapshot`) —
    /// never as a substitute for `open_operation`'s own real guard, whose
    /// `operation_gate` read lock is exactly what a parked waiter (e.g. a
    /// `BEGIN` waiting on an in-flight trigger callback) must NOT hold for
    /// the duration of its wait, since `close()` needs that gate's WRITE
    /// lock to ever complete. Racing this check against a close in
    /// progress is fine either way: a `false` here just means the function
    /// proceeds to its own real, later `open_operation()`/wait logic, which
    /// resolves the race correctly either way.
    fn already_closed(&self) -> bool {
        self.closed.load(Ordering::SeqCst) || self.resource_closed.load(Ordering::SeqCst)
    }
}

impl std::fmt::Debug for Database {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        f.debug_struct("Database")
            .field("instance_id", &self.instance_id)
            .finish_non_exhaustive()
    }
}

